}
for v in sorted(var, key=lambda d:int(d['sample_id'])):
    nm='v_'+v['sample_id']
    inputs.append({'name':nm,'type':'data','format':['xlsx','zip']})
    cmd += \" \\\\\\n  --sample {} \\\""'$(inputs.{}.path)'"\\\"\".format(v['sample_id'], nm)
    tool_inputs[nm]={'src':'hda','id':v['id']}
representation={
 'class':'GalaxyUserTool',
 'id':'blm_chip_carrier_median_20260715_0618',
