 'outputs':[
   {'name':'answer','type':'data','format':'txt','from_work_dir':'answer.txt'},
   {'name':'diagnostics','type':'data','format':'tabular','from_work_dir':'diagnostics.tsv'}
 ]
}
out={'representation':representation,'tool_inputs':tool_inputs}
pathlib.Path('run_trace/udt_payload.json').write_text(json.dumps(out, indent=2))
print(json.dumps({'input_count':len(inputs),'command_chars':len(cmd),'script_chars':len(script),'tool_input_count':len(tool_inputs),'payload_path':'run_trace/udt_payload.json'}, indent=2))
PY"
